<script setup lang="ts">
import IconButton from './IconButton.vue';
import { useModal } from '../modal';
import { ref,onMounted } from 'vue';import { api,json,type Scope } from '../api';import type { Settings,Profile } from '../types';
const dialog=ref<HTMLElement>();
const props=defineProps<{scope:Scope;showStatus:boolean}>(),emit=defineEmits<{close:[];changed:[];clear:[];status:[value:boolean]}>();
const tab=ref('模型'),page=ref(0),status=ref(''),loading=ref(true),busy=ref(false),cfg=ref<Settings>(),profile=ref<Profile>({title:'',avatar:''});
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;status.value='正在处理…';try{await work();}catch(e){status.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{try{const [settings,info]=await Promise.all([api<Settings>('/api/settings',{},props.scope),api<Profile>('/api/conversation/profile',{},props.scope)]);cfg.value={...settings,api_key:''};profile.value=info;}catch(e){status.value=(e as Error).message;}finally{loading.value=false;}});
function save(){return action(async()=>{cfg.value={...await api<Settings>('/api/settings',{method:'POST',body:json(props.scope.channel==='group'?Object.fromEntries(Object.entries(cfg.value||{}).filter(([key])=>!['base_voice','reply_mode'].includes(key))):Object.fromEntries(Object.entries(cfg.value||{}).filter(([key])=>key!=='goal_mode')))},props.scope),api_key:''};status.value=tab.value==='回复'&&cfg.value.reply_mode==='voice'&&!cfg.value.speech_enabled?'已保存；全局语音未开启，目前仍会文字回复':'已保存';emit('changed');});}
function test(){return action(async()=>{const result=await api<{model:string;error?:string}>('/api/test',{method:'POST',body:json(cfg.value),signal:AbortSignal.timeout(120000)},props.scope);if(result.error)throw Error(result.error);status.value='连接正常 · '+result.model;});}
function saveProfile(){return action(async()=>{profile.value=await api<Profile>('/api/conversation/profile',{method:'PUT',body:json({title:profile.value.title,avatar:profile.value.avatar})},props.scope);status.value='已保存';emit('changed');});}
async function fileChanged(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('请选择10MB以内的 PNG、JPEG 或 WebP 图片');const image=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=256;const size=Math.min(image.width,image.height);canvas.getContext('2d')!.drawImage(image,(image.width-size)/2,(image.height-size)/2,size,size,0,0,256,256);image.close();profile.value.avatar=canvas.toDataURL('image/jpeg',.85);}catch(e){status.value=(e as Error).message;}input.value='';}
function setAdult(event:Event){return action(async()=>{const value=(event.target as HTMLInputElement).checked;await api('/api/settings',{method:'POST',body:json({adult_mode:value})},props.scope);if(cfg.value)cfg.value.adult_mode=value;status.value='已保存';});}
async function exportMemory(){return action(async()=>{const result=await api('/api/memory/export',{},props.scope),url=URL.createObjectURL(new Blob([json(result)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='聊天记忆.json';link.click();URL.revokeObjectURL(url);status.value='已导出当前会话记忆';});}
useModal(dialog,()=>emit('close'));
</script>
<template><div class="overlay" @click.self="emit('close')"><section ref="dialog" class="dialog" role="dialog" aria-modal="true" aria-labelledby="chatSettingsTitle"><header><h2 id="chatSettingsTitle">聊天设置</h2><IconButton icon="close" label="关闭" @click="emit('close')"/></header><nav class="tabs"><button v-for="name in ['模型',...(scope.channel==='group'?['群聊']:['人物','回复']),'资料','显示']" :key="name" :class="{active:tab===name}" @click="tab=name;page=0;status=''">{{name}}</button></nav><p class="feedback" role="status" :title="status">{{loading?'正在读取…':status}}</p><div class="dialog-body" v-if="cfg&&!loading">
<template v-if="tab==='模型'"><label class="switch-row"><span>使用主页默认模型</span><input v-model="cfg.inherit_model" type="checkbox" class="switch-input" role="switch"></label><template v-if="page===0"><label>接口地址<input v-model.trim="cfg.base_url" :disabled="cfg.inherit_model"></label><label>模型名称<input v-model.trim="cfg.model" :disabled="cfg.inherit_model"></label><label>API Key <small>{{cfg.api_key_masked}}</small><input v-model.trim="cfg.api_key" type="password" :disabled="cfg.inherit_model" autocomplete="new-password" placeholder="留空保留已有密钥"></label></template><template v-else><label>回复随机性<input v-model.number="cfg.temperature" type="number" min="0" max="2" step="0.1" :disabled="cfg.inherit_model"></label><label>输出上限（0 不限）<input v-model.number="cfg.max_tokens" type="number" min="0" :disabled="cfg.inherit_model"></label></template><nav class="pager"><button @click="page=0" :disabled="page===0">连接</button><button @click="page=1" :disabled="page===1">参数</button></nav></template>
<template v-if="tab==='群聊'"><label class="switch-row"><span>目标模式</span><input type="checkbox" class="switch-input" v-model="cfg.goal_mode"></label><p class="muted">开启后，以你每次发言中的目标推进本轮讨论，达成后自然结束。需要你补充信息或等待实际结果时会暂停。</p><p class="muted">目标判断只在后台进行，聊天中不显示进度或判断结果。每轮仍保留发言上限。</p></template><template v-if="tab==='人物'"><template v-if="page===0"><label>角色个性<textarea v-model="cfg.persona" rows="4" maxlength="4000"/></label><label>与你的关系背景<textarea v-model="cfg.relationship" rows="3" maxlength="2000"/></label></template><template v-else-if="page===1"><label>公开性格<textarea v-model="cfg.public_persona" rows="5" maxlength="1000"/></label><template v-if="scope.channel!=='group'"><label>基础音色<input v-model.trim="cfg.base_voice" maxlength="200" placeholder="填写语音服务提供的音色 ID"></label><p class="muted">由你指定这个角色的固定音色，留空表示尚未配置。</p></template></template><nav class="pager"><IconButton @click="page--" :disabled="page===0" icon="back" label="上一页"/><span>{{page+1}} / 2</span><IconButton @click="page++" :disabled="page===1" icon="next" label="下一页"/></nav></template>
<template v-if="tab==='回复'"><label>回复方式<select class="reply-mode-select" v-model="cfg.reply_mode"><option value="text">文字回复</option><option value="voice">语音回复</option></select></label><p :class="cfg.speech_enabled?'muted':'danger-text'">全局语音：{{cfg.speech_enabled?'已开启':'未开启'}} · 基础音色：{{cfg.base_voice?'已配置':'未配置'}}</p><p v-if="cfg.reply_mode==='voice'&&(!cfg.speech_enabled||!cfg.base_voice||!cfg.speech_configured)" class="danger-text">语音尚不可用：{{!cfg.speech_enabled?'请先在主页模型设置开启语音':!cfg.speech_configured?'请先配置语音模型':'请先在人物设置填写基础音色'}}。</p><p class="muted">只影响当前角色的私聊。选择语音后，每次有台词的回复都会尝试合成语音，不再由角色自行选择。</p><p class="muted">需要在主页“模型 → 语音”开启语音，并在“人物”中填写基础音色。未开启、未配置或合成失败时仍保留文字。</p><p class="muted">括号动作不朗读，语音默认不自动播放。</p></template><template v-if="tab==='资料'"><label>会话名称<input v-model="profile.title" maxlength="60"></label><label>头像<img class="profile-preview" v-if="profile.avatar||profile.default_avatar" :src="profile.avatar||profile.default_avatar" alt="头像预览"><input type="file" accept="image/png,image/jpeg,image/webp" @change="fileChanged"></label><IconButton :icon="profile.default_avatar?'refresh':'trash'" :label="profile.default_avatar?'恢复默认头像':'移除头像'" @click="profile.avatar='';status='保存后生效'"/></template>
<template v-if="tab==='显示'"><label class="switch-row"><span>显示状态栏</span><input type="checkbox" class="switch-input" role="switch" :checked="showStatus" @change="emit('status',($event.target as HTMLInputElement).checked)"></label><label class="switch-row"><span>18+ 内容</span><input type="checkbox" class="switch-input" role="switch" :checked="cfg.adult_mode" @change="setAdult" :disabled="busy"></label><div class="actions"><IconButton icon="trash" label="清空当前显示" @click="emit('clear')"/><IconButton icon="download" label="导出记忆" @click="exportMemory" :disabled="busy"/></div><p class="muted">清空当前显示不删除角色记忆。全部聊天和记忆的重置位于主页设置。</p></template>
</div><footer><template v-if="tab==='模型'"><IconButton icon="connect" label="测试连接" @click="test" :disabled="busy||loading"/><IconButton class="primary" icon="save" label="保存" @click="save" :disabled="busy||loading"/></template><IconButton v-if="tab==='群聊'" class="primary" icon="save" label="保存群聊设置" @click="save" :disabled="busy||loading"/><IconButton v-if="tab==='回复'" class="primary" icon="save" label="保存回复设置" @click="save" :disabled="busy||loading"/><IconButton v-if="tab==='人物'" class="primary" icon="save" label="保存人物设定" @click="save" :disabled="busy||loading"/><IconButton v-if="tab==='资料'" class="primary" icon="save" label="保存会话资料" @click="saveProfile" :disabled="busy||loading"/></footer></section></div></template>
